"""Readable, deterministic sample fixtures; categories are never fixture inputs.

All brands and review narratives are fictional. Hosts use reserved .example
domains. Stable keys identify scenarios independently of their order or titles.
"""
from dataclasses import dataclass

from core.models import Intake

BRANDS = {
    "Astervale": "astervale.example",
    "Lumifern": "lumifern.example",
    "Velora Works": "veloraworks.example",
    "Northpetal": "northpetal.example",
}
SAMPLE_NOTICE = "Sample investigation (fictional). No evidence is supplied with this scenario."


@dataclass(frozen=True)
class Scenario:
    key: str
    source: str
    url: str
    brand: str
    title: str
    description: str
    status: str = "New"
    review_notes: str = ""

    @property
    def verdict(self) -> str:
        return {
            "New": "Pending review", "Reviewing": "Inconclusive",
            "Validated": "Confirmed violation", "Escalated": "Confirmed violation",
            "False Positive": "No violation found",
        }[self.status]

    def intake(self) -> Intake:
        notes = SAMPLE_NOTICE
        if self.review_notes:
            notes += "\nFictional sample review: " + self.review_notes
        return Intake(self.source, self.url, self.brand, BRANDS[self.brand],
                      self.title, self.description, notes)


